package internal

import (
	"maps"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

type Config struct {
	Workspaces    map[string]string `yaml:"workspaces"`
	AgentCommand  string            `yaml:"agent_command"`
	UseTmux       *bool             `yaml:"use_tmux"`
	InjectInto    string            `yaml:"inject_into"`
	TestCommand   string            `yaml:"test_command"`
	AutoHooks     *bool             `yaml:"auto_hooks"`
	BranchPrefix  string            `yaml:"branch_prefix"`
	WorkspaceMode string            `yaml:"workspace_mode,omitempty"`
}

func (c Config) GetAgentCommand() string {
	if c.AgentCommand != "" {
		return c.AgentCommand
	}
	return "claude"
}

// ConfigPath returns the global config path.
func ConfigPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "tws", "config.yaml")
}

func repoConfigPath() string {
	root, err := RepoRoot()
	if err != nil {
		return ""
	}
	return filepath.Join(root, ".tws", "config.yaml")
}

func loadConfigFile(path string) Config {
	if path == "" {
		return Config{}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}
	}
	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return Config{}
	}
	return cfg
}

// LoadConfig loads the global config, then merges per-repo config on top.
// Per-repo values override global values when set.
func LoadConfig() Config {
	cfg := loadConfigFile(ConfigPath())
	repo := loadConfigFile(repoConfigPath())

	if repo.AgentCommand != "" {
		cfg.AgentCommand = repo.AgentCommand
	}
	if repo.UseTmux != nil {
		cfg.UseTmux = repo.UseTmux
	}
	if repo.InjectInto != "" {
		cfg.InjectInto = repo.InjectInto
	}
	if repo.TestCommand != "" {
		cfg.TestCommand = repo.TestCommand
	}
	if repo.AutoHooks != nil {
		cfg.AutoHooks = repo.AutoHooks
	}
	if repo.BranchPrefix != "" {
		cfg.BranchPrefix = repo.BranchPrefix
	}
	if repo.WorkspaceMode != "" {
		cfg.WorkspaceMode = repo.WorkspaceMode
	}
	if len(repo.Workspaces) > 0 {
		if cfg.Workspaces == nil {
			cfg.Workspaces = make(map[string]string)
		}
		maps.Copy(cfg.Workspaces, repo.Workspaces)
	}

	return cfg
}

// SaveConfigFile writes a config to the given path.
func SaveConfigFile(path string, cfg Config) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := yaml.Marshal(&cfg)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

// RepoConfigPath exports the per-repo config path for the config command.
func RepoConfigPath() string {
	return repoConfigPath()
}

// LoadConfigFile loads a single config file (exported for the config command).
func LoadConfigFile(path string) Config {
	return loadConfigFile(path)
}

// TemplatePath returns the template directory path.
// Per-repo (.tws/templates/) takes priority over global (~/.config/tws/templates/).
// Returns empty string if neither exists.
func TemplatePath() string {
	// Per-repo first
	repoPath := repoConfigPath()
	if repoPath != "" {
		repoTemplates := filepath.Join(filepath.Dir(repoPath), "templates")
		if info, err := os.Stat(repoTemplates); err == nil && info.IsDir() {
			return repoTemplates
		}
	}

	// Global
	home, _ := os.UserHomeDir()
	globalTemplates := filepath.Join(home, ".config", "tws", "templates")
	if info, err := os.Stat(globalTemplates); err == nil && info.IsDir() {
		return globalTemplates
	}

	return ""
}

package internal

import (
	"os"
	"path/filepath"
	"strings"
)

const workspaceMarker = ".tws-workspace"

// DetectWorkspaceRoot checks if cwd is inside an existing workspace.
// Returns the workspace root or empty string.
func DetectWorkspaceRoot(cwd string, cfg Config) string {
	// Tier 1: Walk up looking for .tws-workspace marker
	dir := cwd
	for {
		if _, err := os.Stat(filepath.Join(dir, workspaceMarker)); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}

	// Tier 2: Check if cwd is inside any configured workspace path
	for _, ws := range cfg.Workspaces {
		absWs, err := filepath.Abs(ws)
		if err != nil {
			continue
		}
		absCwd, err := filepath.Abs(cwd)
		if err != nil {
			continue
		}
		if strings.HasPrefix(absCwd, absWs+string(filepath.Separator)) || absCwd == absWs {
			return absWs
		}
	}

	// Tier 3: Check if cwd is inside ~/tws
	home, _ := os.UserHomeDir()
	globalDefault := filepath.Join(home, "tws")
	absCwd, _ := filepath.Abs(cwd)
	if strings.HasPrefix(absCwd, globalDefault+string(filepath.Separator)) || absCwd == globalDefault {
		return globalDefault
	}

	return ""
}

// resolveTwsRoot contains the resolution logic with injectable dependencies.
// It routes through resolveWorkspaceMetadataRoot to honour workspace mode
// while preserving byte-for-byte external outputs for existing callers.
func resolveTwsRoot(envRoot string, cwd string, repoRoot string, repoErr error, cfg Config) string {
	// 0. TWS_ROOT env var — always wins
	if envRoot != "" {
		return envRoot
	}

	// 1. Already inside a workspace? Return that root.
	if wsRoot := DetectWorkspaceRoot(cwd, cfg); wsRoot != "" {
		return wsRoot
	}

	// 2. Route through workspace resolver (handles mode + config + sibling).
	if root := resolveWorkspaceMetadataRoot(repoRoot, repoErr, cfg); root != "" {
		return root
	}

	// 3. Global fallback (no repo detected).
	home, _ := os.UserHomeDir()
	return filepath.Join(home, "tws")
}

func TwsRoot() string {
	repoRoot, repoErr := MainRepoRoot()
	cfg := LoadConfig()
	cwd, _ := os.Getwd()
	return resolveTwsRoot(os.Getenv("TWS_ROOT"), cwd, repoRoot, repoErr, cfg)
}

func FeaturePath(feature string) string {
	return filepath.Join(TwsRoot(), feature)
}

func WorktreePath(feature, branch string) string {
	return filepath.Join(FeaturePath(feature), "worktrees", branch)
}

// DetectFeatureFromCwd detects the current feature name from the working directory.
// Works when cwd is inside a worktree: <workspace>/<feature>/worktrees/<branch>/
// Returns feature name and feature path, or empty strings if not detected.
func DetectFeatureFromCwd() (string, string) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", ""
	}

	wsRoot := TwsRoot()
	absWs, _ := filepath.Abs(wsRoot)
	absCwd, _ := filepath.Abs(cwd)

	// Check if cwd is inside the workspace
	if !strings.HasPrefix(absCwd, absWs+string(filepath.Separator)) {
		return "", ""
	}

	// Get the relative path from workspace root
	rel, err := filepath.Rel(absWs, absCwd)
	if err != nil {
		return "", ""
	}

	// First component is the feature name
	parts := strings.SplitN(rel, string(filepath.Separator), 2)
	if len(parts) == 0 {
		return "", ""
	}

	feature := parts[0]
	featurePath := filepath.Join(absWs, feature)

	// Verify it's actually a feature dir (has stack.yaml or worktrees/)
	if _, err := os.Stat(filepath.Join(featurePath, "worktrees")); err == nil {
		return feature, featurePath
	}
	if _, err := os.Stat(filepath.Join(featurePath, "stack.yaml")); err == nil {
		return feature, featurePath
	}

	return "", ""
}

// ListFeatures returns the names of all feature directories in the workspace.
func ListFeatures() []string {
	wsRoot := TwsRoot()
	entries, err := os.ReadDir(wsRoot)
	if err != nil {
		return nil
	}
	var features []string
	for _, e := range entries {
		if e.IsDir() && e.Name() != ".tws-workspace" {
			features = append(features, e.Name())
		}
	}
	return features
}

// ListBranches returns the branch names for a feature from stack.yaml,
// or from the worktrees directory if no stack exists.
func ListBranches(feature string) []string {
	featurePath := FeaturePath(feature)
	stack, err := LoadStack(featurePath)
	if err == nil && len(stack.Branches) > 0 {
		var names []string
		for _, e := range stack.Branches {
			names = append(names, e.Name)
		}
		return names
	}

	// Fallback: list worktree directories
	wtDir := filepath.Join(featurePath, "worktrees")
	entries, err := os.ReadDir(wtDir)
	if err != nil {
		return nil
	}
	var names []string
	for _, e := range entries {
		if e.IsDir() {
			names = append(names, e.Name())
		}
	}
	return names
}

package internal

import (
	"crypto/sha256"
	"fmt"
	"os"
	"path/filepath"
)

// WorkspaceMode describes how tws stores metadata for a repository.
type WorkspaceMode string

const (
	// ModeExternal stores metadata in a sibling directory (<repo>.tws).
	// This is the default and preserves the original behaviour.
	ModeExternal WorkspaceMode = "external"

	// ModeCheckout stores metadata inside the repository at <repo>/.tws.
	ModeCheckout WorkspaceMode = "checkout"
)

// Capabilities reports what features a given workspace mode supports.
// Checkout mode retains logical stacks and decisions but cannot create
// linked worktrees because it stores metadata inside the repo tree.
type Capabilities struct {
	Stack           bool // logical stack/decisions
	LinkedWorktrees bool // git worktree add support
}

// Workspace is the resolved identity and layout for a single repository.
type Workspace struct {
	// RepoRoot is the absolute, cleaned repository path.
	RepoRoot string

	// Mode is the resolved workspace mode (external or checkout).
	Mode WorkspaceMode

	// MetadataRoot is the absolute path that holds tws state.
	// External: <repo>.tws   Checkout: <repo>/.tws
	MetadataRoot string

	// StableID is a deterministic identifier derived from the canonical
	// repo path. Movement of the repository on disk will change this
	// value until a global registry supplies persisted IDs.
	StableID string

	// Caps describes mode-specific capabilities.
	Caps Capabilities
}

// capsFor returns capabilities for a given mode.
func capsFor(mode WorkspaceMode) Capabilities {
	switch mode {
	case ModeCheckout:
		return Capabilities{Stack: true, LinkedWorktrees: false}
	default: // external
		return Capabilities{Stack: true, LinkedWorktrees: true}
	}
}

// stableID computes a deterministic hex ID from a canonical path.
// It uses the absolute, cleaned path (with symlinks resolved when
// possible). Relocating the repository changes the ID; a future
// global registry will provide persistent identifiers.
func stableID(canonicalPath string) string {
	h := sha256.Sum256([]byte(canonicalPath))
	return fmt.Sprintf("%x", h[:8])
}

// canonicalize returns an absolute, cleaned path. It resolves symlinks
// when possible; on error it falls back to filepath.Abs + filepath.Clean.
func canonicalize(p string) string {
	if resolved, err := filepath.EvalSymlinks(p); err == nil {
		return filepath.Clean(resolved)
	}
	return cleanAbsolute(p)
}

func cleanAbsolute(p string) string {
	abs, err := filepath.Abs(p)
	if err != nil {
		return filepath.Clean(p)
	}
	return filepath.Clean(abs)
}

// parseMode interprets a raw string as a WorkspaceMode.
// Unknown values return empty string and false.
func parseMode(raw string) (WorkspaceMode, bool) {
	switch WorkspaceMode(raw) {
	case ModeExternal:
		return ModeExternal, true
	case ModeCheckout:
		return ModeCheckout, true
	case "":
		return "", false
	default:
		return "", false
	}
}

// ResolveCurrentWorkspace determines the workspace for a given repo root
// and config. It checks, in order:
//
//  1. Explicit workspace_mode in the per-repo config (.tws/config.yaml).
//  2. Presence of .tws/config.yaml without workspace_mode -> external (legacy).
//  3. Default: external.
//
// This function is a pure resolver; it never calls TwsRoot or any path
// function that might recurse back into resolution.
func ResolveCurrentWorkspace(repoRoot string, cfg Config) Workspace {
	original := cleanAbsolute(repoRoot)
	canon := canonicalize(repoRoot)

	// Read per-repo config to look for explicit workspace_mode.
	repoConfigFile := filepath.Join(canon, ".tws", "config.yaml")
	repoCfg := loadConfigFile(repoConfigFile)

	var mode WorkspaceMode
	if m, ok := parseMode(repoCfg.WorkspaceMode); ok {
		mode = m
	} else {
		// Legacy: .tws/config.yaml exists but no workspace_mode -> external.
		// Or no config at all -> external.
		mode = ModeExternal
	}

	var metadataRoot string
	switch mode {
	case ModeCheckout:
		metadataRoot = filepath.Join(canon, ".tws")
	default: // external
		metadataRoot = resolveExternalRoot(original, canon, cfg)
	}

	return Workspace{
		RepoRoot:     canon,
		Mode:         mode,
		MetadataRoot: metadataRoot,
		StableID:     stableID(canon),
		Caps:         capsFor(mode),
	}
}

// resolveExternalRoot computes the external metadata root for a repo.
// Priority: original-path config key -> canonical-path config key -> sibling directory.
// This preserves legacy config entries that intentionally use a symlinked repo path.
func resolveExternalRoot(originalRepoRoot, canonicalRepoRoot string, cfg Config) string {
	if root, ok := cfg.Workspaces[originalRepoRoot]; ok {
		return root
	}
	if root, ok := cfg.Workspaces[canonicalRepoRoot]; ok {
		return root
	}
	return canonicalRepoRoot + ".tws"
}

// FeaturePath returns the feature directory within the workspace.
func (w Workspace) FeaturePath(feature string) string {
	return filepath.Join(w.MetadataRoot, feature)
}

// WorktreePath returns the worktree directory within a feature.
func (w Workspace) WorktreePath(feature, worktree string) string {
	return filepath.Join(w.MetadataRoot, feature, "worktrees", worktree)
}

// resolveWorkspaceMetadataRoot is the backend boundary function.
// It resolves the metadata root for a given repo, accounting for
// workspace mode. Called by resolveTwsRoot to route through the
// workspace layer while preserving byte-for-byte external outputs.
//
// If repoRoot is empty or repoErr is non-nil, this returns empty
// string (caller should fall back to home dir or env override).
func resolveWorkspaceMetadataRoot(repoRoot string, repoErr error, cfg Config) string {
	if repoErr != nil || repoRoot == "" {
		return ""
	}
	ws := ResolveCurrentWorkspace(repoRoot, cfg)
	return ws.MetadataRoot
}

// metadataRootExists checks if the metadata root directory exists on disk.
func metadataRootExists(root string) bool {
	info, err := os.Stat(root)
	return err == nil && info.IsDir()
}

package internal

import (
	"os"
	"path/filepath"
	"testing"
)

// ---------- helpers ----------

func setupTestRepo(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	// Initialize a bare-minimum repo structure (no actual git needed for resolution)
	return dir
}

func writeTwsConfig(t *testing.T, dir string, content string) {
	t.Helper()
	twsDir := filepath.Join(dir, ".tws")
	if err := os.MkdirAll(twsDir, 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(twsDir, "config.yaml"), []byte(content), 0644); err != nil {
		t.Fatal(err)
	}
}

// ---------- ResolveCurrentWorkspace tests ----------

func TestResolveWorkspace_CheckoutMode(t *testing.T) {
	repo := setupTestRepo(t)
	writeTwsConfig(t, repo, "workspace_mode: checkout\n")

	ws := ResolveCurrentWorkspace(repo, Config{})

	if ws.Mode != ModeCheckout {
		t.Errorf("expected checkout, got %s", ws.Mode)
	}
	want := filepath.Join(canonicalize(repo), ".tws")
	if ws.MetadataRoot != want {
		t.Errorf("MetadataRoot = %s, want %s", ws.MetadataRoot, want)
	}
}

func TestResolveWorkspace_CheckoutMetadataRootIsInsideRepo(t *testing.T) {
	repo := setupTestRepo(t)
	writeTwsConfig(t, repo, "workspace_mode: checkout\n")

	ws := ResolveCurrentWorkspace(repo, Config{})

	canon := canonicalize(repo)
	// MetadataRoot must be <repo>/.tws, NOT the external sibling.
	if ws.MetadataRoot != filepath.Join(canon, ".tws") {
		t.Errorf("checkout MetadataRoot should be inside repo, got %s", ws.MetadataRoot)
	}
	// Verify it's NOT the sibling path
	if ws.MetadataRoot == canon+".tws" {
		t.Error("checkout MetadataRoot must not be the external sibling")
	}
}

func TestResolveWorkspace_ExplicitExternalMode(t *testing.T) {
	repo := setupTestRepo(t)
	writeTwsConfig(t, repo, "workspace_mode: external\n")

	ws := ResolveCurrentWorkspace(repo, Config{})

	if ws.Mode != ModeExternal {
		t.Errorf("expected external, got %s", ws.Mode)
	}
	canon := canonicalize(repo)
	want := canon + ".tws"
	if ws.MetadataRoot != want {
		t.Errorf("MetadataRoot = %s, want %s", ws.MetadataRoot, want)
	}
}

func TestResolveWorkspace_LegacyConfigNoMode(t *testing.T) {
	// .tws/config.yaml exists but no workspace_mode -> defaults to external.
	repo := setupTestRepo(t)
	writeTwsConfig(t, repo, "agent_command: claude\n")

	ws := ResolveCurrentWorkspace(repo, Config{})

	if ws.Mode != ModeExternal {
		t.Errorf("expected external for legacy config, got %s", ws.Mode)
	}
	canon := canonicalize(repo)
	if ws.MetadataRoot != canon+".tws" {
		t.Errorf("MetadataRoot = %s, want sibling", ws.MetadataRoot)
	}
}

func TestResolveWorkspace_InvalidMode(t *testing.T) {
	repo := setupTestRepo(t)
	writeTwsConfig(t, repo, "workspace_mode: foobar\n")

	ws := ResolveCurrentWorkspace(repo, Config{})

	// Invalid mode falls back to external.
	if ws.Mode != ModeExternal {
		t.Errorf("expected external for invalid mode, got %s", ws.Mode)
	}
}

func TestResolveWorkspace_NoTwsDir(t *testing.T) {
	// Repo with no .tws directory at all -> external.
	repo := setupTestRepo(t)

	ws := ResolveCurrentWorkspace(repo, Config{})

	if ws.Mode != ModeExternal {
		t.Errorf("expected external when no .tws exists, got %s", ws.Mode)
	}
}

func TestResolveWorkspace_TwsDirExistsNoConfig(t *testing.T) {
	// .tws directory exists but no config.yaml -> external (just a dir marker).
	repo := setupTestRepo(t)
	if err := os.MkdirAll(filepath.Join(repo, ".tws"), 0755); err != nil {
		t.Fatal(err)
	}

	ws := ResolveCurrentWorkspace(repo, Config{})

	if ws.Mode != ModeExternal {
		t.Errorf("expected external when .tws exists without config, got %s", ws.Mode)
	}
}

func TestResolveWorkspace_ExternalWithConfigWorkspaces(t *testing.T) {
	repo := setupTestRepo(t)
	canon := canonicalize(repo)
	customRoot := t.TempDir()
	cfg := Config{
		Workspaces: map[string]string{
			canon: customRoot,
		},
	}

	ws := ResolveCurrentWorkspace(repo, cfg)

	if ws.MetadataRoot != customRoot {
		t.Errorf("MetadataRoot = %s, want %s (from config workspaces)", ws.MetadataRoot, customRoot)
	}
}

func TestResolveWorkspace_ExternalWithSymlinkConfigKey(t *testing.T) {
	realRepo := setupTestRepo(t)
	linkRoot := t.TempDir()
	linkRepo := filepath.Join(linkRoot, "repo-link")
	if err := os.Symlink(realRepo, linkRepo); err != nil {
		t.Fatal(err)
	}
	customRoot := t.TempDir()
	cfg := Config{Workspaces: map[string]string{cleanAbsolute(linkRepo): customRoot}}

	ws := ResolveCurrentWorkspace(linkRepo, cfg)
	if ws.MetadataRoot != customRoot {
		t.Errorf("MetadataRoot = %s, want %s from symlink config key", ws.MetadataRoot, customRoot)
	}
}

func TestResolveWorkspace_ExternalSiblingDefault(t *testing.T) {
	repo := setupTestRepo(t)
	canon := canonicalize(repo)

	ws := ResolveCurrentWorkspace(repo, Config{})

	want := canon + ".tws"
	if ws.MetadataRoot != want {
		t.Errorf("MetadataRoot = %s, want %s", ws.MetadataRoot, want)
	}
}

// ---------- Capabilities tests ----------

func TestCapabilities_ExternalMode(t *testing.T) {
	caps := capsFor(ModeExternal)
	if !caps.Stack {
		t.Error("external mode should support stacks")
	}
	if !caps.LinkedWorktrees {
		t.Error("external mode should support linked worktrees")
	}
}

func TestCapabilities_CheckoutMode(t *testing.T) {
	caps := capsFor(ModeCheckout)
	if !caps.Stack {
		t.Error("checkout mode should support stacks")
	}
	if caps.LinkedWorktrees {
		t.Error("checkout mode should NOT support linked worktrees")
	}
}

// ---------- StableID tests ----------

func TestStableID_Deterministic(t *testing.T) {
	id1 := stableID("/foo/bar")
	id2 := stableID("/foo/bar")
	if id1 != id2 {
		t.Errorf("stableID not deterministic: %s != %s", id1, id2)
	}
	if len(id1) != 16 { // 8 bytes = 16 hex chars
		t.Errorf("stableID length = %d, want 16", len(id1))
	}
}

func TestStableID_DifferentPaths(t *testing.T) {
	id1 := stableID("/foo/bar")
	id2 := stableID("/foo/baz")
	if id1 == id2 {
		t.Error("stableID should differ for different paths")
	}
}

func TestCanonicalize_AbsoluteClean(t *testing.T) {
	repo := setupTestRepo(t)
	// Create a subdirectory so EvalSymlinks can resolve the full path
	sub := filepath.Join(repo, "subdir")
	if err := os.MkdirAll(sub, 0755); err != nil {
		t.Fatal(err)
	}
	dirty := sub + "/.."
	canon := canonicalize(dirty)
	want := canonicalize(repo)
	if canon != want {
		t.Errorf("canonicalize(%q) = %q, want %q", dirty, canon, want)
	}
}

// ---------- FeaturePath / WorktreePath through Workspace ----------

func TestWorkspace_FeaturePath(t *testing.T) {
	ws := Workspace{MetadataRoot: "/data/myproject.tws"}
	got := ws.FeaturePath("auth")
	want := "/data/myproject.tws/auth"
	if got != want {
		t.Errorf("FeaturePath = %s, want %s", got, want)
	}
}

func TestWorkspace_WorktreePath(t *testing.T) {
	ws := Workspace{MetadataRoot: "/data/myproject.tws"}
	got := ws.WorktreePath("auth", "fix-login")
	want := "/data/myproject.tws/auth/worktrees/fix-login"
	if got != want {
		t.Errorf("WorktreePath = %s, want %s", got, want)
	}
}

func TestWorkspace_CheckoutFeaturePath(t *testing.T) {
	ws := Workspace{
		MetadataRoot: "/repo/.tws",
		Mode:         ModeCheckout,
	}
	got := ws.FeaturePath("billing")
	want := "/repo/.tws/billing"
	if got != want {
		t.Errorf("FeaturePath = %s, want %s", got, want)
	}
}

func TestWorkspace_CheckoutWorktreePath(t *testing.T) {
	ws := Workspace{
		MetadataRoot: "/repo/.tws",
		Mode:         ModeCheckout,
	}
	got := ws.WorktreePath("billing", "add-stripe")
	want := "/repo/.tws/billing/worktrees/add-stripe"
	if got != want {
		t.Errorf("WorktreePath = %s, want %s", got, want)
	}
}

// ---------- resolveTwsRoot backward compat ----------

func TestResolveTwsRoot_ExternalBackwardCompat(t *testing.T) {
	// Ensure the refactored resolveTwsRoot produces byte-for-byte
	// identical results for existing external scenarios.

	t.Run("env_var_wins", func(t *testing.T) {
		got := resolveTwsRoot("/custom/root", "/somewhere", "/some/repo", nil, Config{})
		if got != "/custom/root" {
			t.Errorf("expected /custom/root, got %s", got)
		}
	})

	t.Run("config_workspace_map", func(t *testing.T) {
		cfg := Config{
			Workspaces: map[string]string{
				"/repos/myproject": "/data/workspaces/myproject",
			},
		}
		got := resolveTwsRoot("", "/somewhere", "/repos/myproject", nil, cfg)
		if got != "/data/workspaces/myproject" {
			t.Errorf("expected /data/workspaces/myproject, got %s", got)
		}
	})

	t.Run("sibling_default", func(t *testing.T) {
		got := resolveTwsRoot("", "/somewhere", "/repos/myproject", nil, Config{})
		if got != "/repos/myproject.tws" {
			t.Errorf("expected /repos/myproject.tws, got %s", got)
		}
	})
}

func TestResolveTwsRoot_CheckoutMode(t *testing.T) {
	repo := setupTestRepo(t)
	writeTwsConfig(t, repo, "workspace_mode: checkout\n")
	canon := canonicalize(repo)

	got := resolveTwsRoot("", "/somewhere", canon, nil, Config{})
	want := filepath.Join(canon, ".tws")
	if got != want {
		t.Errorf("expected %s for checkout mode, got %s", want, got)
	}
}

func TestResolveTwsRoot_NoRepo(t *testing.T) {
	home, _ := os.UserHomeDir()
	want := filepath.Join(home, "tws")
	got := resolveTwsRoot("", "/somewhere", "", os.ErrNotExist, Config{})
	if got != want {
		t.Errorf("expected %s, got %s", want, got)
	}
}

